import { render, Component, rerender, version } from 'inferno'
import { createElement } from 'inferno-create-element'
import assert from 'assert'
import App, { state, sequences, props } from 'cerebral'
import { Container, connect } from '.'

// Detect Inferno version for version-specific test cases
const isInfernoVersion6Plus =
  version && parseInt(version.split('.')[0], 10) >= 6

// Test helper for component references
const componentRefs = new Map()
function getComponentRef(Component) {
  const refKey = {}

  const WrappedWithRef = (props) => {
    return createElement(Component, {
      ...props,
      ref: (instance) => {
        if (instance) componentRefs.set(refKey, instance)
        else componentRefs.delete(refKey)
      },
    })
  }

  return {
    WrappedWithRef,
    getRef: () => componentRefs.get(refKey),
  }
}

describe('Inferno', () => {
  let container, $, mount
  before(() => {
    container = document.createElement('div')
    document.body.appendChild(container)
    $ = (s) => container.querySelector(s)
    mount = (jsx) => render(jsx, container)
  })

  afterEach(() => {
    mount(null)
    container.innerHTML = ''
    componentRefs.clear()
  })

  after(() => {
    document.body.removeChild(container)
    container = null
  })

  describe('container', () => {
    it('should be able to expose app', () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      mount(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual($('div').innerHTML, 'bar')
    })
    it('should throw when no app provided', () => {
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      assert.throws(
        () => {
          mount(
            <Container>
              <TestComponent />
            </Container>
          )
        },
        (err) => {
          if (err instanceof Error) {
            return (
              err.message ===
              'Cerebral - You are not passing a Cerebral app to Container'
            )
          }
        }
      )
    })
    it('should throw when container component is not provided', () => {
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      assert.throws(
        () => {
          mount(<TestComponent />)
        },
        (err) => {
          if (err instanceof Error) {
            return (
              err.message ===
              'Cerebral - Can not find controller, did you remember to use the Container component? Read more at: https://cerebraljs.com/docs/views/inferno.html'
            )
          }
        }
      )
    })
    it('should be able to unregister component from container after unmounting component', () => {
      const app = App(
        {
          state: {
            foo: 'bar',
          },
        },
        {
          devtools: {
            init() {},
            send() {},
            updateWatchMap() {},
            updateComputedMap() {},
            sendWatchMap() {},
          },
        }
      )
      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        (props) => {
          return <div>{props.foo}</div>
        }
      )
      const tree = mount(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      if (!isInfernoVersion6Plus) {
        assert.strictEqual(tree.$LI.children.view.isUnmounted, false)
      }
      assert.strictEqual($('div').innerHTML, 'bar')

      mount(null)

      if (!isInfernoVersion6Plus) {
        assert.strictEqual(tree.$LI.children.view.isUnmounted, true)
      }
      assert.deepStrictEqual(app.dependencyStore.getAllUniqueEntities(), [])
    })
  })

  describe('connect', () => {
    it('should convert component to json', () => {
      const app = App({
        state: {
          foo: 'bar',
        },
      })
      const MyComponent = (props) => {
        return <div>{props.foo}</div>
      }
      MyComponent.displayName = 'Test'

      const TestComponent = connect(
        {
          foo: state`foo`,
        },
        MyComponent
      )

      if (!isInfernoVersion6Plus) {
        const tree = mount(
          <Container app={app}>
            <TestComponent />
          </Container>
        )
        assert.strictEqual(tree.$LI.children.toJSON(), 'Test')
      } else {
        mount(
          <Container app={app}>
            <TestComponent />
          </Container>
        )
        assert.strictEqual(TestComponent.toJSON(), 'Test')
      }

      assert.strictEqual($('div').innerHTML, 'bar')
    })
    it('should render ones where multiple state matches', () => {
      const app = App({
        state: {
          foo: 'bar',
          bar: 'foo',
        },
        sequences: {
          test: [
            ({ store }) => {
              store.set('foo', 'bar2')
              store.set('bar', 'foo2')
            },
          ],
        },
      })
      let renderCount = 0
      const TestComponent = connect(
        {
          foo: state`foo`,
          bar: state`bar`,
        },
        (props) => {
          renderCount++
          return <div>{props.foo}</div>
        }
      )
      mount(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual($('div').innerHTML, 'bar')
      assert.strictEqual(renderCount, 1)
      app.getSequence('test')()

      if (rerender) {
        rerender()
      }

      assert.strictEqual(renderCount, 2)
    })
    it('should rerender affected components', () => {
      if (!isInfernoVersion6Plus) {
        let renderCount = 0
        const app = App({
          state: {
            foo: 'bar',
          },
          sequences: {
            methodCalled: [({ store }) => store.set('foo', 'bar2')],
          },
        })
        class TestComponentClass2 extends Component {
          render() {
            renderCount++
            return <div />
          }
        }
        const TestComponent2 = connect({}, TestComponentClass2)
        class TestComponentClass extends Component {
          callSignal() {
            this.props.methodCalled()
          }

          render() {
            renderCount++
            return (
              <div>
                <TestComponent2 />
              </div>
            )
          }
        }
        const TestComponent = connect(
          {
            foo: state`foo`,
            methodCalled: sequences`methodCalled`,
          },
          TestComponentClass
        )
        const tree = mount(
          <Container app={app}>
            <TestComponent />
          </Container>
        )
        const component = tree.$LI.children.$LI.children
        component.callSignal()
        assert.strictEqual(renderCount, 3)
      } else {
        let renderCount = 0
        const app = App({
          state: {
            foo: 'bar',
          },
          sequences: {
            methodCalled: [({ store }) => store.set('foo', 'bar2')],
          },
        })

        const TestComponent2 = connect(
          { foo: state`foo` },
          class extends Component {
            render() {
              renderCount++
              return <div />
            }
          }
        )

        const TestComponent = connect(
          { foo: state`foo` },
          class extends Component {
            render() {
              renderCount++
              return (
                <div>
                  <TestComponent2 />
                </div>
              )
            }
          }
        )

        mount(
          <Container app={app}>
            <TestComponent />
          </Container>
        )

        renderCount = 0

        app.getSequence('methodCalled')()
        if (rerender) {
          rerender()
        }

        assert.strictEqual(renderCount, 2)
      }
    })
    it('should allow props tag and computed', () => {
      const app = App({
        state: {
          foo: {
            baz: 'mip',
          },
          aComputed: (get) => get(props`foo`),
        },
      })
      const TestComponent = connect(
        {
          a: state`aComputed`,
          b: props`bar.id`,
          c: state`foo.${props`propKey`}`,
        },
        ({ a, b, c }) => {
          return <div>{a + b + c}</div>
        }
      )
      mount(
        <Container app={app}>
          <TestComponent foo="bar" bar={{ id: '1' }} propKey="baz" />
        </Container>
      )
      assert.strictEqual($('div').innerHTML, 'bar1mip')
    })
    it('should update on props change', () => {
      const app = App({})
      let componentInstance = null

      class TestComponentClass2 extends Component {
        render() {
          return <div>{this.props.foo}</div>
        }
      }
      const TestComponent2 = connect({}, TestComponentClass2)
      class TestComponentClass extends Component {
        constructor(props) {
          super(props)
          this.state = { foo: 'bar' }
          componentInstance = this
        }

        changePath() {
          this.setState({
            foo: 'bar2',
          })
        }

        render() {
          return (
            <span>
              <TestComponent2 foo={this.state.foo} />
            </span>
          )
        }
      }
      const TestComponent = connect({}, TestComponentClass)

      mount(
        <Container app={app}>
          <TestComponent />
        </Container>
      )

      assert.strictEqual($('div').innerHTML, 'bar')

      componentInstance.changePath()

      if (rerender) {
        rerender()
      }

      assert.strictEqual($('div').innerHTML, 'bar2')
    })
    it('should be able to unregister component after unmounting', () => {
      const app = App({
        state: { foo: 'bar' },
      })

      let wasUnmounted = false

      class TestComponentClass extends Component {
        componentWillUnmount() {
          wasUnmounted = true
        }

        render() {
          return <div>{this.props.foo}</div>
        }
      }

      const TestComponent = connect({ foo: state`foo` }, TestComponentClass)

      const { WrappedWithRef, getRef } = getComponentRef(TestComponent)

      mount(
        <Container app={app}>
          <WrappedWithRef />
        </Container>
      )

      assert.strictEqual($('div').innerHTML, 'bar')

      const componentRef = getRef()
      mount(null)

      assert.strictEqual(wasUnmounted, true)
      if (componentRef) {
        assert.strictEqual(componentRef.isComponentUnmounted, true)
      }

      assert.deepStrictEqual(app.dependencyStore.getAllUniqueEntities(), [])
    })
    it('should expose a merge signature', () => {
      const app = App({
        state: {
          foo: 'bar',
          bar: 'baz',
        },
      })

      const TestComponent = connect(
        {
          a: props`foo`,
          b: state`foo`,
        },
        (deps, props, get) => {
          return {
            a: deps.a,
            b: deps.b,
            c: props.foo + '!!!',
            d: get(state`bar`),
          }
        },
        ({ a, b, c, d }) => {
          return <div>{a + b + c + d}</div>
        }
      )

      mount(
        <Container app={app}>
          <TestComponent foo="bar" />
        </Container>
      )

      assert.strictEqual($('div').innerHTML, 'barbarbar!!!baz')
    })
  })
})
